mapper.select:
/*	marketResearch.selectMarketResearchCount */
	SELECT
		count(RESEARCH_IDX) as cnt
	FROM
		lab_market_research
	WHERE 1 = 1
		AND IS_DELETE = 'N'
		
			 
			AND DOC_OWNER = #{userId} 
			
		    
		    AND DOC_OWNER IN (
		    	SELECT USER_ID from lab_team_manager_view ltmv
				WHERE ltmv.TEAM_MANAGER_ID = #{userId}
		    ) 
		    
		    
		    
		    
		    
			 AND DOC_OWNER = #{userId}

/* marketResearch.selectMarketResearchList */ SELECT tmp.* , CASE WHEN tmp.TRIP_TYPE = 'I' THEN '국내' WHEN tmp.TRIP_TYPE = 'O' THEN '해외' END AS TRIP_TYPE_TXT , FN_GET_USER_NAME(tmp.REG_USER) as REG_USER_NAME , FN_GET_USER_NAME(tmp.DOC_OWNER) as DOC_OWNER_NAME , FN_GET_USER_NAME(tmp.DOC_OWNER) as USER_NAME , FN_GET_CODE_NAME('DOC_STATUS', tmp.STATUS) AS STATUS_TXT FROM ( SELECT row_number() over (order by RESEARCH_IDX DESC) as rnum , RESEARCH_IDX , PLAN_IDX , TRIP_TYPE , TITLE , RESEARCH_DATE , COST , REG_USER , DOC_OWNER , STATUS , IS_DELETE , VERSION_NO , IS_LAST FROM lab_market_research WHERE 1 = 1
AND DOC_OWNER = #{userId}
AND DOC_OWNER IN ( SELECT USER_ID from lab_team_manager_view ltmv WHERE ltmv.TEAM_MANAGER_ID = #{userId} )
AND DOC_OWNER = #{userId}
AND IS_DELETE = 'N'
)tmp WHERE rnum between #{startRow} and #{endRow}

mapper.insert:
/*	marketResearch.insertMarketResearch */
INSERT INTO lab_market_research(
	RESEARCH_IDX
	
	, PLAN_IDX
	
	, TITLE
	, TRIP_TYPE
	, RESEARCH_DATE
	, COST
	, REG_USER
	, DOC_OWNER
	, STATUS
	, IS_LAST
	, IS_DELETE
	, VERSION_NO
)VALUES(
	#{idx}
	
	, #{planIdx}
	
	, #{title}
	, #{tripType}
	, #{researchDate}
	, #{cost}
	, #{userId}
	, #{userId}
	, #{status}
	, 'Y'
	, 'N'
	, 1		
)

mapper.update:
/*	marketResearch.selectMarketResearchAddInfoList */
UPDATE 
	lab_market_research
SET
	TITLE = #{title}	
	
	, PLAN_IDX = #{planIdx}
	
	, TRIP_TYPE = #{tripType}	
	, RESEARCH_DATE = #{researchDate}	
	, COST = #{cost}	
WHERE 1 = 1
	AND RESEARCH_IDX = #{idx}

mapper.delete:
/*	marketResearch.deleteMarketResearchAddInfo */
DELETE
FROM lab_market_research_add_info
WHERE 1 = 1
	AND RESEARCH_IDX = #{idx}

/*	marketResearch.deleteMarketResearchUser */
DELETE
FROM lab_market_research_user
WHERE 1 = 1
	AND RESEARCH_IDX = #{idx}
